def trap(height):
    i, j = 0, len(height) - 1
    lmax = rmax = water = 0
    while i < j:
        if height[i] < height[j]:
            lmax = max(lmax, height[i]); water += lmax - height[i]; i += 1
        else:
            rmax = max(rmax, height[j]); water += rmax - height[j]; j -= 1
    return water

solution.cpp:
int trap(vector<int>& h) {
    int i = 0, j = (int)h.size() - 1, lm = 0, rm = 0, w = 0;
    while (i < j) {
        if (h[i] < h[j]) { lm = max(lm, h[i]); w += lm - h[i]; i++; }
        else { rm = max(rm, h[j]); w += rm - h[j]; j--; }
    }
    return w;
}
